import { runtimeProjectionOf } from '../../design-system/registry/snapshot';

const BANNER = [
  '/**',
  ' * GENERATED BY PANDAMSTYLE - DO NOT EDIT.',
  ' * Generated from the canonical design-system snapshot.',
  ' */',
].join('\n');
const lexicalCompare = (a, b) => (a < b ? -1 : a > b ? 1 : 0);

function literal(value) {
  return JSON.stringify(value);
}

function union(values) {
  return values.length === 0 ? 'never' : values.map(literal).join(' | ');
}

function typeRecord(entries, renderValue) {
  if (entries.length === 0) return 'Readonly<Record<never, never>>';
  return [
    '{',
    ...entries.map(
      ([key, value]) => `  readonly ${literal(key)}: ${renderValue(value)};`,
    ),
    '}',
  ].join('\n');
}

function recipeDomainType(snapshot) {
  const rows = snapshot.vocabulary.publicRecipeIds.map((recipeId) => [
    recipeId,
    snapshot.tooling.candidateDomains.recipes.byRecipe[recipeId].values,
  ]);
  return typeRecord(rows, (axes) => {
    const axisRows = Object.entries(axes);
    if (axisRows.length === 0) return 'Readonly<Record<never, never>>';
    return [
      '{',
      ...axisRows.map(
        ([axis, values]) =>
          `    readonly ${literal(axis)}: readonly [${values.map(literal).join(', ')}];`,
      ),
      '  }',
    ].join('\n');
  });
}

function recipeSelectionTypes(snapshot) {
  const axes = snapshot.tooling.candidateDomains.recipes.byRecipe;
  return snapshot.vocabulary.publicRecipeIds
    .map((recipeId, index) => {
      const definition = axes[recipeId];
      const properties = definition.axes
        .map((axis) => {
          const domain = definition.values[axis];
          const value = domain.every(
            (entry) => entry === 'true' || entry === 'false',
          )
            ? domain.includes('true') && domain.includes('false')
              ? 'boolean'
              : domain.includes('true')
                ? 'true'
                : 'false'
            : union(domain);
          return `  readonly ${literal(axis)}?: ${value};`;
        })
        .join('\n');
      const defaults = typeRecord(
        Object.entries(snapshot.tooling.manifest.recipes[recipeId].defaults),
        (value) => literal(value),
      );
      return [
        `type RecipeSelection_${index} = Readonly<{`,
        properties,
        '}>;',
        `type RecipeDefaults_${index} = ${defaults};`,
      ].join('\n');
    })
    .join('\n\n');
}

function recipeRuntimeType(snapshot) {
  const axes = snapshot.tooling.candidateDomains.recipes.byRecipe;
  return snapshot.vocabulary.publicRecipeIds
    .map((recipeId, index) => {
      const definition = axes[recipeId];
      const slots = snapshot.tooling.manifest.recipes[recipeId].slots ?? [];
      const selection = `RecipeSelection_${index}`;
      const defaults = `RecipeDefaults_${index}`;
      const result = slots.length > 0 ? `RecipeSlots_${index}` : 'StyleRef';
      const axisTuple = definition.axes.map(literal).join(', ');
      const variantMap = typeRecord(
        definition.axes.map((axis) => [axis, definition.values[axis]]),
        (values) => `readonly [${values.map(literal).join(', ')}]`,
      );
      return [
        ...(slots.length > 0
          ? [
              `type RecipeSlots_${index} = Readonly<{ ${slots
                .map((slot) => `readonly ${literal(slot)}: StyleRef;`)
                .join(' ')} }>;`,
            ]
          : []),
        `type RecipeRef_${index} = ((selection?: ${selection} | null) => ${result}) & Readonly<{`,
        `  recipeId: ${literal(recipeId)};`,
        `  axisOrder: readonly [${axisTuple}];`,
        `  variantKeys: readonly [${axisTuple}];`,
        `  variantMap: ${variantMap};`,
        `  defaultVariants: ${defaults};`,
        `  splitVariantProps(props?: Readonly<Record<string, unknown>>): readonly [${selection}, Readonly<Record<string, unknown>>];`,
        `  getVariantProps(selection?: ${selection} | null): ${selection};`,
        '}>;',
      ].join('\n');
    })
    .join('\n\n');
}

function manifestTokenType(snapshot) {
  return typeRecord(
    snapshot.vocabulary.tokens
      .filter((token) => token.visibility === 'public')
      .map((token) => [token.tokenId, token]),
    (token) => `Readonly<{ readonly category: ${literal(token.category)} }>`,
  );
}

function manifestSemanticTokenType(snapshot) {
  const publicTargets = new Set(snapshot.vocabulary.publicTokenPaths);
  return typeRecord(
    snapshot.vocabulary.semanticTokens
      .filter((token) => token.visibility === 'public')
      .map((token) => [token.tokenId, token]),
    (token) =>
      `Readonly<{ readonly category: ${literal(token.category)}; readonly kind: 'alias';${
        token.ref != null && publicTargets.has(token.ref)
          ? ` readonly ref: ${literal(token.ref)};`
          : ''
      } }>`,
  );
}

function manifestRecipeType(snapshot) {
  const rows = snapshot.vocabulary.publicRecipeIds.map((recipeId) => [
    recipeId,
    { recipeId, ...snapshot.tooling.manifest.recipes[recipeId] },
  ]);
  return typeRecord(rows, (recipe) => {
    const axisEntries = recipe.axisOrder.map((axis) => [
      axis,
      recipe.axes[axis],
    ]);
    const defaults = Object.entries(recipe.defaults);
    const defaultsType =
      defaults.length === 0
        ? 'Readonly<Record<never, never>>'
        : typeRecord(defaults, (value) => literal(value));
    const slots = recipe.slots ?? [];
    const compoundVariants = recipe.compoundVariants ?? [];
    const compoundTypes = compoundVariants.map((compound) => {
      const when = typeRecord(
        Object.entries(compound.when ?? {}),
        (values) =>
          `readonly [${(Array.isArray(values) ? values : [values])
            .map(literal)
            .join(', ')}]`,
      );
      return `Readonly<{ readonly when: ${when} }>`;
    });
    const compoundsType =
      compoundTypes.length === 0
        ? 'readonly []'
        : `readonly [${compoundTypes.join(', ')}]`;
    const slotField = snapshot.capabilities?.slots
      ? `\n  readonly slots: readonly [${slots.map(literal).join(', ')}];`
      : '';
    const compoundField = snapshot.capabilities?.compoundVariants
      ? `\n  readonly compoundVariants: ${compoundsType};`
      : '';
    return `Readonly<{\n  readonly axisOrder: readonly [${recipe.axisOrder.map(literal).join(', ')}];\n  readonly axes: ${typeRecord(axisEntries, (values) => `readonly [${values.map(literal).join(', ')}]`)};\n  readonly defaults: ${defaultsType};${slotField}${compoundField}\n}>`;
  });
}

function themeDetailsType(snapshot, includeBase = true) {
  const themeNames = includeBase
    ? snapshot.vocabulary.themes
    : snapshot.vocabulary.themes.filter((themeName) => themeName !== 'base');
  const rows = themeNames.map((themeName) => {
    const details =
      themeName === 'base'
        ? { extends: null, declaredOverrides: [], overrides: [], remaps: {} }
        : (snapshot.tooling.manifest.themeDetails?.[themeName] ?? {
            extends: 'base',
            declaredOverrides: [],
            overrides: [],
            remaps: {},
          });
    const remaps = typeRecord(Object.entries(details.remaps ?? {}), (target) =>
      literal(target),
    );
    return [
      themeName,
      `Readonly<{ extends: ${literal(details.extends)}; declaredOverrides: readonly [${(details.declaredOverrides ?? []).map(literal).join(', ')}]; overrides: readonly [${(details.overrides ?? []).map(literal).join(', ')}]; remaps: ${remaps} }>`,
    ];
  });
  return typeRecord(rows, (value) => value);
}

function themeTokenValueType(snapshot) {
  const publicPaths = snapshot.vocabulary.publicTokenPaths;
  return typeRecord(
    snapshot.vocabulary.themes.map((themeName) => {
      const values = publicPaths.map((tokenId) => [
        tokenId,
        themeName === 'base'
          ? snapshot.registry.resolvedValues[tokenId]
          : (snapshot.registry.themes[themeName]?.[tokenId] ??
            snapshot.registry.resolvedValues[tokenId]),
      ]);
      return [themeName, typeRecord(values, (value) => literal(value))];
    }),
    (value) => value,
  );
}

function themeTokenRemapType(snapshot) {
  return typeRecord(
    snapshot.vocabulary.themes.map((themeName) => [
      themeName,
      themeName === 'base'
        ? typeRecord([], () => 'never')
        : typeRecord(
            Object.entries(
              snapshot.tooling.manifest.themeDetails?.[themeName]?.remaps ?? {},
            ),
            (target) => literal(target),
          ),
    ]),
    (value) => value,
  );
}

function patternParameterType(parameter) {
  let valueType =
    parameter.category != null
      ? `CategoryTokenReference<${literal(parameter.category)}>`
      : union(parameter.values ?? []);
  if (parameter.responsive === true) {
    valueType = `PmsResponsive<${valueType}>`;
  }
  return valueType;
}

function manifestPatternsType(snapshot) {
  const catalog = snapshot.tooling.manifest.patterns ?? {};
  return typeRecord(
    Object.entries(catalog).sort(([a], [b]) => lexicalCompare(a, b)),
    (pattern) => {
      const parameters = typeRecord(
        Object.entries(pattern.parameters ?? {}),
        (parameter) => {
          const fields = [];
          if (parameter.responsive === true || parameter.responsive === false) {
            fields.push(
              `readonly responsive: ${literal(parameter.responsive)}`,
            );
          }
          if (parameter.category != null) {
            fields.push(`readonly category: ${literal(parameter.category)}`);
          }
          if (parameter.token === true) fields.push('readonly token: true');
          if (Array.isArray(parameter.values)) {
            fields.push(
              `readonly values: readonly [${parameter.values.map(literal).join(', ')}]`,
            );
          }
          return `Readonly<{ ${fields.join('; ')} }>`;
        },
      );
      return `Readonly<{ readonly patternId: ${literal(pattern.patternId)}; readonly parameters: ${parameters} }>`;
    },
  );
}

function patternTypeLines(snapshot) {
  if (snapshot.capabilities?.patterns !== true) return [];
  const catalog = snapshot.tooling.manifest.patterns ?? {};
  const patternIds = Object.keys(catalog).sort(lexicalCompare);
  const declarations = patternIds.map((patternId) => {
    const typeName = `${patternId[0].toUpperCase()}${patternId.slice(1)}PatternOptions`;
    const properties = Object.entries(catalog[patternId].parameters).map(
      ([name, parameter]) => [name, patternParameterType(parameter)],
    );
    const options =
      properties.length === 0
        ? 'Readonly<Record<never, never>>'
        : `Readonly<{ ${properties
            .map(([name, value]) => `readonly ${literal(name)}?: ${value};`)
            .join(' ')} }>`;
    return `export type ${typeName} = ${options};`;
  });
  const namespaceMembers = patternIds.map((patternId) => {
    const typeName = `${patternId[0].toUpperCase()}${patternId.slice(1)}PatternOptions`;
    return `${literal(patternId)}(options?: ${typeName}): StyleRef;`;
  });
  return [
    'export type PmsResponsive<Value> = Value | Readonly<{ base?: Value; default?: Value } & Partial<Record<PmsConditionName, Value>>>;',
    `export type PatternName = ${union(patternIds)};`,
    ...declarations,
    `export declare const patterns: Readonly<{ ${namespaceMembers.join(' ')} }>;`,
  ];
}

function manifestConditionsType(snapshot) {
  const rows = snapshot.vocabulary.conditions.map(
    (condition) =>
      `Readonly<{ name: ${literal(condition.name)}; definition: ${literal(condition.definition)}; kind: ${literal(condition.kind)} }>`,
  );
  return rows.length === 0 ? 'readonly []' : `readonly [${rows.join(', ')}]`;
}

/** Generate the application-facing declarations from the same snapshot as JS. */
export function generateDesignSystemDeclarations(snapshot) {
  const runtime = runtimeProjectionOf(snapshot);
  const identity = runtime.identity;
  const capabilities = snapshot.capabilities ?? {};
  const capabilityLiteral = `Readonly<{ slots: ${literal(capabilities.slots === true)}; compoundVariants: ${literal(capabilities.compoundVariants === true)}; patterns: ${literal(capabilities.patterns === true)}; rawDynamicStyles: false }>`;
  const categories = snapshot.vocabulary.tokenCategories;
  const categoryProperties = Object.entries(
    snapshot.tooling.manifest.supportedProperties.categories,
  );
  const structuralSets = Object.entries(
    snapshot.tooling.manifest.supportedProperties.structuralSets,
  );
  const structuralNumbers = Object.keys(
    snapshot.tooling.manifest.supportedProperties.structuralNumbers,
  );
  const structuralNumberRows = Object.entries(
    snapshot.tooling.manifest.supportedProperties.structuralNumbers,
  );
  const compositeFormsRejected =
    snapshot.tooling.manifest.supportedProperties.compositeFormsRejected;
  const conditions = snapshot.vocabulary.conditionNames;
  const recipeIds = snapshot.vocabulary.publicRecipeIds;
  const recipeAxisNames = [
    ...new Set(
      recipeIds.flatMap(
        (recipeId) =>
          snapshot.tooling.candidateDomains.recipes.byRecipe[recipeId].axes,
      ),
    ),
  ];
  const recipeAxisValueTypes = [
    ...new Set(
      recipeIds.flatMap((recipeId) => {
        const definition =
          snapshot.tooling.candidateDomains.recipes.byRecipe[recipeId];
        return definition.axes.map((axis) => {
          const domain = definition.values[axis];
          return domain.every((value) => value === 'true' || value === 'false')
            ? domain.includes('true') && domain.includes('false')
              ? 'boolean'
              : domain.includes('true')
                ? 'true'
                : 'false'
            : union(domain);
        });
      }),
    ),
  ];
  const themeIds = snapshot.vocabulary.themes;
  const tokenPathByCategory = typeRecord(
    categories.map((category) => [
      category,
      snapshot.vocabulary.tokenPathsByCategory[category],
    ]),
    (paths) => union(paths),
  );
  const propertyCategories = typeRecord(categoryProperties, (category) =>
    literal(category),
  );
  const structuralPropertyValues = typeRecord(structuralSets, (values) =>
    union(values),
  );
  const structuralNumberTypes = typeRecord(
    structuralNumberRows,
    (range) => `Readonly<{ min: ${literal(range.min)}; max: number }>`,
  );
  const recipeMap = typeRecord(
    recipeIds.map((recipeId, index) => [recipeId, index]),
    (index) => `RecipeRef_${index}`,
  );
  const themeMap = typeRecord(
    themeIds.map((themeId) => [themeId, themeId]),
    (themeId) => `ThemeRef & Readonly<{ themeId: ${literal(themeId)} }>`,
  );
  const tokenPaths = snapshot.vocabulary.publicTokenPaths;
  const patternsTypes = patternTypeLines(snapshot);
  const manifestPatternsField = capabilities.patterns
    ? `\n  patterns: ${manifestPatternsType(snapshot)};`
    : '';
  const identityLiteral = `Readonly<{
  abiVersion: 1;
  compilerContractVersion: ${literal(identity.compilerContractVersion)};
  designSystem: Readonly<{ systemId: ${literal(identity.systemId)}; registryDigest: ${literal(identity.registryDigest)} }>;
  manifestSchemaVersion: 1;
  capabilities: ${capabilityLiteral};
}>`;
  const manifestLiteral = `Readonly<{
  schemaVersion: 1;
  systemId: ${literal(identity.systemId)};
  registryDigest: ${literal(identity.registryDigest)};
  abiVersion: 1;
  compilerContractVersion: 'pms-0.1';
  manifestSchemaVersion: 1;
  capabilities: ${capabilityLiteral};
  tokens: ${manifestTokenType(snapshot)};
  semanticTokens: ${manifestSemanticTokenType(snapshot)};
  tokenCategories: readonly [${categories.map(literal).join(', ')}];
  conditions: ${manifestConditionsType(snapshot)};
  themes: readonly [${snapshot.tooling.manifest.themes.map(literal).join(', ')}];
  themeDetails: ${themeDetailsType(snapshot, false)};
  ${manifestPatternsField.trimStart()}
  recipes: ${manifestRecipeType(snapshot)};
  supportedProperties: Readonly<{ categories: PropertyCategories; structuralSets: StructuralPropertyValues; structuralNumbers: ${structuralNumberTypes}; compositeFormsRejected: readonly [${compositeFormsRejected.map(literal).join(', ')}] }>;
}>`;
  const categorySpecificTypes = categories
    .map((category) => {
      const name = `${category[0].toUpperCase()}${category.slice(1)}TokenPath`;
      return `export type ${name} = TokenPathByCategory<${literal(category)}>;`;
    })
    .join('\n');

  return [
    BANNER,
    "import type { StyleRef, ThemeRef, TokenRef as CoreTokenRef } from '@pandamstyle/core';",
    '',
    `export type PublicTokenPath = ${union(tokenPaths)};`,
    `export type PublicTokenCategory = ${union(categories)};`,
    `type TokenPathDomains = ${tokenPathByCategory};`,
    'export type TokenPathByCategory<Category extends PublicTokenCategory> = TokenPathDomains[Category];',
    categorySpecificTypes,
    'type TokenCategoryForPath<Path extends PublicTokenPath> = { [Category in PublicTokenCategory]: Path extends TokenPathByCategory<Category> ? Category : never }[PublicTokenCategory];',
    'export type PandamStyleTokenRef<Category extends PublicTokenCategory, Path extends TokenPathByCategory<Category>> = CoreTokenRef<Category, Path>;',
    '',
    `export type PmsConditionName = ${union(conditions)};`,
    `export type ThemeName = ${union(themeIds)};`,
    `type ThemeDetails = ${themeDetailsType(snapshot)};`,
    `type ThemeTokenValues = ${themeTokenValueType(snapshot)};`,
    `type ThemeTokenRemaps = ${themeTokenRemapType(snapshot)};`,
    "export type ThemeParent<Name extends ThemeName> = ThemeDetails[Name]['extends'];",
    "export type ThemeOverrideTokenPath<Name extends ThemeName> = ThemeDetails[Name]['overrides'][number];",
    'export type ThemeTokenValue<Name extends ThemeName, Path extends PublicTokenPath> = ThemeTokenValues[Name][Path];',
    'export type ThemeTokenRemap<Name extends ThemeName, Path extends PublicTokenPath> = Path extends keyof ThemeTokenRemaps[Name] ? ThemeTokenRemaps[Name][Path] : never;',
    `export type PublicRecipeId = ${union(recipeIds)};`,
    `type RecipeAxes = ${recipeDomainType(snapshot)};`,
    recipeSelectionTypes(snapshot),
    recipeRuntimeType(snapshot),
    "type VariantDomainValue<Domain extends readonly string[]> = Exclude<Domain[number], 'true' | 'false'> extends never ? ('true' extends Domain[number] ? ('false' extends Domain[number] ? boolean : true) : false) : Domain[number];",
    'type RecipeAxisDomainValue<Domain> = Domain extends readonly string[] ? VariantDomainValue<Domain> : never;',
    'export type PublicRecipeAxis<Id extends PublicRecipeId = PublicRecipeId> = Id extends PublicRecipeId ? keyof RecipeAxes[Id] & string : never;',
    'export type PublicRecipeAxisValue<Id extends PublicRecipeId = PublicRecipeId> = Id extends PublicRecipeId ? { [Axis in keyof RecipeAxes[Id] & string]: RecipeAxisDomainValue<RecipeAxes[Id][Axis]> }[keyof RecipeAxes[Id] & string] : never;',
    `export type RecipeAxisName = ${union(recipeAxisNames)};`,
    `export type RecipeAxisValue = ${recipeAxisValueTypes.length === 0 ? 'never' : recipeAxisValueTypes.join(' | ')};`,
    '',
    `type PropertyCategories = ${propertyCategories};`,
    `type StructuralPropertyValues = ${structuralPropertyValues};`,
    `type StructuralNumberProperties = ${union(structuralNumbers)};`,
    'type StyleProperty = keyof PropertyCategories | keyof StructuralPropertyValues | StructuralNumberProperties;',
    'type CategoryTokenReference<Category extends string> = Category extends PublicTokenCategory ? CoreTokenRef<Category, TokenPathByCategory<Category>> : never;',
    'type CategoryValue<Property extends keyof PropertyCategories> = CategoryTokenReference<PropertyCategories[Property]>;',
    'type PropertyValue<Property extends StyleProperty> = Property extends keyof PropertyCategories ? CategoryValue<Property> : Property extends keyof StructuralPropertyValues ? StructuralPropertyValues[Property] : number;',
    "type ConditionValue<Property extends StyleProperty> = Partial<Record<PmsConditionName | 'base' | 'default', PropertyValue<Property>>>;",
    'export type PmsStyleRule = { [Property in StyleProperty]?: PropertyValue<Property> | ConditionValue<Property> };',
    'export type PmsStyleSheet = Readonly<Record<string, PmsStyleRule>>;',
    '',
    'export declare function token<Path extends PublicTokenPath>(path: Path): CoreTokenRef<TokenCategoryForPath<Path>, Path>;',
    'export declare function create<Sheet extends PmsStyleSheet>(sheet: Sheet): Readonly<{ [Namespace in keyof Sheet]: StyleRef }>;',
    'export type PmsCompositionInput = StyleRef | ThemeRef | readonly PmsCompositionInput[] | null | undefined | false;',
    'export declare const props: (...inputs: readonly PmsCompositionInput[]) => Readonly<{ className: string }> | Readonly<Record<string, never>>;',
    `export declare const recipes: ${recipeMap};`,
    `export declare const themes: ${themeMap};`,
    ...patternsTypes,
    `export declare const manifest: ${manifestLiteral};`,
    `export declare const __pandamstyle: ${identityLiteral};`,
    '',
  ]
    .filter(Boolean)
    .join('\n');
}

/**
 * Cache key for declarations owned by a project session.
 *
 * The generated declaration exposes the canonical registry digest and
 * compiler identity, and its remaining literal unions are projections of that
 * same canonical registry. Supported-property vocabulary is included because
 * it is also rendered into the public declarations. Keep this beside the
 * generator so a new declaration input cannot silently bypass invalidation.
 */
export function designDeclarationCacheKey(snapshot) {
  const identity = runtimeProjectionOf(snapshot).identity;
  // Registry identity is not a complete declaration-cache key. The canonical
  // registry digest can be stable across authored reordering while generated
  // declarations preserve vocabulary and manifest order. Keep every input
  // consumed by generateDesignSystemDeclarations in this projection so a
  // remove/restore or reorder cannot reuse text produced for another snapshot.
  return JSON.stringify({
    identity,
    capabilities: snapshot.capabilities ?? {},
    vocabulary: snapshot.vocabulary,
    registry: {
      resolvedValues: snapshot.registry.resolvedValues,
      themes: snapshot.registry.themes,
    },
    tooling: {
      candidateDomains: snapshot.tooling.candidateDomains,
      manifest: snapshot.tooling.manifest,
    },
  });
}
